$ErrorActionPreference='Stop'
$inbox='D:\Claude\jev\docs\agents\grok_inbox.md'
if (-not (Test-Path -LiteralPath $inbox)) { throw 'missing inbox' }
$utf8 = New-Object System.Text.UTF8Encoding $false
$add = $utf8.GetString([Convert]::FromBase64String(''))
$before=(Get-Item -LiteralPath $inbox).Length
$fs=[IO.File]::Open($inbox,'Open','Read','ReadWrite'); $fs.Seek(-1,'End')|Out-Null; $last=$fs.ReadByte(); $fs.Close()
if ($last -ne 10) { $add = "`n" + $add }
[IO.File]::AppendAllText($inbox, $add, $utf8)
$after=(Get-Item -LiteralPath $inbox).Length
"before=$before after=$after added=" + ($after-$before)
$fs=[IO.File]::Open($inbox,'Open','Read','ReadWrite'); $h=New-Object byte[] 3; [void]$fs.Read($h,0,3); $fs.Close(); "first3=" + [BitConverter]::ToString($h)
